pm.test("Returns 200", ()=>pm.response.to.have.status(200));
var raw=pm.response.json(); var r=(raw&&"response" in raw)?raw.response:raw;
var uKey=parseInt(pm.environment.get("upcoming_key"));
var entries=(r.needsAttention||[]).filter(e=>e.compoundFormKey===uKey);
pm.test("upcoming compound in needsAttention", ()=>pm.expect(entries.length).to.be.above(0));
if (entries.length>0) {
  var e=entries[0];
  pm.test("reason is upcoming", ()=>pm.expect(e.reason).to.eql("upcoming"));
  var ctrl=new Date(pm.environment.get("upcoming_ctrl_date")+"T00:00:00Z");
  ctrl.setUTCDate(ctrl.getUTCDate()+45);
  var actual=new Date(e.deadlineAt);
  var diffDays=Math.abs((actual-ctrl)/86400000);
  pm.test("deadlineAt ≈ controlDate+45d (within 2d tolerance)", ()=>pm.expect(diffDays).to.be.below(2));
}

